int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int result = -EINVAL;
    struct socket *new_sock = NULL;

    if (current->nsproxy->net_ns != sock_net(sk))
        return -EINVAL;

    if (sctp_assoc_lookup(sk, id) == NULL)
        return -ENOENT;

    if (sctp_has_pending_threads(sk, id))
        return -EBUSY;

    if (!sctp_can_be_pulled(sk))
        return -EINVAL;

    result = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type, sk->sk_protocol, &new_sock);
    if (result < 0)
        return result;

    result = sctp_copy_properties(sk, new_sock->sk);
    if (result < 0) {
        sock_release(new_sock);
        return result;
    }

    result = sctp_migrate_association(sk, id, new_sock->sk);
    if (result < 0) {
        sock_release(new_sock);
        return result;
    }

    *sockp = new_sock;
    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (!sctp_assoc_lookup_id(sk, id))
        return -ENOENT;

    if (sctp_has_pending_bh(sk))
        return -EBUSY;

    if (sk->sk_type != SOCK_STREAM)
        return -ESOCKTNOSUPPORT;

    ret = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type,
                           sk->sk_protocol, sockp);
    if (ret)
        return ret;

    sctp_copy_sock(*sockp, sk, id);

    ret = sctp_migrate_assoc(sk, *sockp, id);
    if (ret < 0)
        sock_release(*sockp);
    else
        ret = 0;

    return ret;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (!sctp_assoc_lookup(sk, id))
        return -ENOENT;

    if (sk->sk_sleep && waitqueue_active(sk->sk_sleep))
        return -EBUSY;

    if (sk->sk_type != SOCK_STREAM)
        return -EINVAL;

    ret = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type, sk->sk_protocol, sockp);
    if (ret < 0)
        return ret;

    struct sock *new_sk = (*sockp)->sk;
    new_sk->sk_state = sk->sk_state;
    new_sk->sk_bound_dev_if = sk->sk_bound_dev_if;
    new_sk->sk_priority = sk->sk_priority;

    sctp_migrate_association(sk, new_sk, id);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (sctp_id2assoc(sk, id) == NULL)
        return -EINVAL;

    if (sctp_has_buffer_waiters(sk, id))
        return -EBUSY;

    if (sk->sk_type != SOCK_SEQPACKET && sk->sk_type != SOCK_STREAM)
        return -EINVAL;

    ret = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type,
                           sk->sk_protocol, sockp);
    if (ret < 0)
        return ret;

    ret = sctp_do_peeloff(sk, id, *sockp);
    if (ret < 0)
        sock_release(*sockp);

    return ret;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (!sctp_assoc_lookup_id(sk, id))
        return -EINVAL;

    if (sctp_wait_for_sndbuf(sk))
        return -EBUSY;

    if (sk->sk_type != SOCK_STREAM)
        return -EINVAL;

    ret = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type, sk->sk_protocol, sockp);
    if (ret)
        return ret;

    sctp_copy_sock(*sockp, sk, id);
    sctp_association_migrate(sctp_id2assoc(sk, id), *sockp);

    return 0;
}
